var gr = new GlideRecord('sys_metadata');
gr.addQuery('sys_id=1279edf7936d2210d90d367f3bba1025');
gr.query();
if (gr.next()) {
    var filePath = gr.sys_class_name + '_' + gr.sys_id + '.xml';
    gs.log(filePath);
}


var instanceName = gs.getProperty('instance_name');
var appID = gs.getProperty('REST.git.push.appID');
var repoID = gs.getProperty('REST.git.push.RepoID');
var gdt = new GlideDateTime();

var request = new sn_ws.RESTMessageV2("Metadata Push To Git", "POST");
request.setEndpoint('https://' + instanceName + '.service-now.com/api/sn_devstudio/v1/vcs/apps/' + appID + '/repos/' + repoID + '/commits');
request.setRequestHeader("Accept", "application/json");
request.setRequestHeader('Content-Type', 'application/json');

// Construct request body with delete operation
var requestBody = {
    commitMessage: "Auto-delete commit for file: " + filePath + " at " + gdt,
    delete: [filePath]
};
request.setRequestBody(JSON.stringify(requestBody));

var response = request.execute();
var responseBody = JSON.parse(response.getBody());
var pwSysId = responseBody["result"]["progressId"];
gs.log('HTTP Status: ' + response.getStatusCode());
gs.log('Response Body: ' + response.getBody());
gs.log('pwsysId  :  ' + pwSysId);

